import Database from "better-sqlite3";
import { instrumentSqlite, log } from "./telemetry.ts";
import { drizzle, type BetterSQLite3Database } from "drizzle-orm/better-sqlite3";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import { mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { config } from "./config.ts";
import * as schema from "./db/schema.ts";

export { schema };
export type DB = BetterSQLite3Database<typeof schema> & { $client: Database.Database };

/** Generated by `vp run db:generate` from server/db/schema.ts. */
export const migrationsFolder = fileURLToPath(new URL("./db/migrations", import.meta.url));

export function openDb(path: string): DB {
  if (path !== ":memory:") mkdirSync(dirname(resolve(path)), { recursive: true });
  const sqlite = instrumentSqlite(new Database(path));
  sqlite.pragma("journal_mode = WAL");
  sqlite.pragma("foreign_keys = ON");
  sqlite.pragma("busy_timeout = 5000");
  sqlite.pragma("synchronous = NORMAL");
  const db = drizzle(sqlite, { schema });
  runMigrations(db, path);
  return db;
}

/**
 * Apply any pending migrations. Runs on every startup (server, dev server, CLI), so a new deployment
 * upgrades its database before serving requests. A failing migration throws and the process does not start.
 */
function runMigrations(db: DB, path: string) {
  const applied = () => {
    const exists = db.$client
      .prepare("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = '__drizzle_migrations'")
      .get();
    return exists ? (db.$client.prepare("SELECT count(*) AS n FROM __drizzle_migrations").get() as { n: number }).n : 0;
  };
  const before = applied();
  migrate(db, { migrationsFolder });
  const after = applied();
  if (after > before && path !== ":memory:") {
    log.info({ db: path, applied: after - before, total: after }, "database migrations applied");
  }
}

// Survive Vite dev-server module reloads by caching on globalThis.
const g = globalThis as unknown as { __rentalDb?: DB };
export function getDb(): DB {
  g.__rentalDb ??= openDb(config.databasePath);
  return g.__rentalDb;
}

/** Test hook: replace the process-wide DB. */
export function setDb(db: DB) {
  g.__rentalDb = db;
}

/**
 * Run `fn` in a transaction. Services call each other with the same `db` handle; better-sqlite3 has a
 * single connection, so nested calls simply join the outer transaction.
 */
export function tx<T>(db: DB, fn: () => T): T {
  if (db.$client.inTransaction) return fn();
  return db.transaction(() => fn(), { behavior: "immediate" });
}

export function closeDb(db: DB) {
  db.$client.close();
}
